const DemoListingProfiles={"1":{"name":"Maya Chen","role":"Co-founder & product lead","about":"We help independent shops manage bookings, payments, and everyday customer relationships.","context":"Our current setup asks new owners to make too many decisions before they understand the product. Your project will simplify the first-session experience without hiding important setup choices.","responsibilities":["Review the current onboarding flow and a sample of anonymized support notes.","Run five short usability sessions using a prepared recruitment plan.","Map the first-session journey and identify the three highest-friction moments.","Prototype an accessible onboarding flow with clear empty and error states.","Walk engineering through interaction decisions and handoff notes."],"deliverables":["Research synthesis and prioritized problem statement","Clickable Figma prototype covering the happy path and recovery states","Annotated components, content suggestions, and a handoff walkthrough"],"collaboration":"Weekly 30-minute product review; async feedback in a shared project thread.","timeline":["Week 1: discovery and usability sessions","Week 2: prototype and feedback","Week 3: polish and engineering handoff"],"fit":"Figma, interview planning, clear visual hierarchy, and explaining design tradeoffs.","photo":"assets/people/creator-1.svg","teamSize":"6 people"},"2":{"name":"Noah Rivera","role":"Founder & engineering lead","about":"Canopy turns operational sustainability data into decisions small businesses can act on.","context":"The team has a calculation service but no clear way for customers to explore its output. Build a dashboard that explains where emissions estimates come from and makes comparisons understandable.","responsibilities":["Explore a documented API and a supplied synthetic emissions dataset.","Build responsive summary cards, time-series views, and category comparisons.","Support loading, empty, error, and partial-data states.","Add keyboard access, readable contrast, and descriptive chart alternatives.","Write component tests and document setup and data assumptions."],"deliverables":["React dashboard with three documented views","Tested chart interactions and accessible tabular alternatives","README, component notes, and a recorded handoff"],"collaboration":"Two engineering check-ins per week; pull-request feedback from the founder.","timeline":["Week 1: data contract and wireframe","Weeks 2–3: implementation and tests","Week 4: review and handoff"],"fit":"React, JavaScript, data visualization, and communicating uncertainty in data.","photo":"assets/people/creator-2.svg","teamSize":"3 people"},"3":{"name":"Priya Shah","role":"Head of product & analytics","about":"Orbit is building a financial-planning product that helps people make sense of everyday money decisions.","context":"We want to understand which early product actions are associated with repeat usage. Use a de-identified sample dataset to produce a careful analysis the team can reproduce, without treating correlation as causation.","responsibilities":["Audit event definitions and document missing or inconsistent records.","Use SQL to define activation and retention cohorts.","Explore patterns in a reproducible Python notebook.","Check whether conclusions change with different cohort definitions.","Present three testable product questions and explain the analysis limits."],"deliverables":["Cleaned analysis tables and a data-quality log","SQL queries and a reproducible notebook","A short findings deck with recommended experiments"],"collaboration":"Weekly analytics review and an async question log with the product team.","timeline":["Days 1–3: data audit","Days 4–8: cohort analysis","Days 9–10: findings and walkthrough"],"fit":"SQL joins, Python data analysis, cohort definitions, and clear written reasoning.","photo":"assets/people/creator-3.svg","teamSize":"8 people"},"4":{"name":"Amara Brooks","role":"Co-founder & community lead","about":"Gather helps neighborhood makers introduce their products to nearby customers.","context":"We are preparing a small local launch and need a practical plan that a two-person team can execute. Focus on one audience and one clear conversion goal, with lightweight measurement.","responsibilities":["Interview the founders and review the product positioning.","Define a primary local audience and its motivations.","Identify community partners and outreach channels using public information.","Draft a four-week content calendar and reusable launch assets.","Set realistic KPIs and a simple weekly reporting template."],"deliverables":["Audience and positioning brief","Four-week content calendar and six campaign drafts","Partner outreach templates and a KPI sheet"],"collaboration":"One planning call and one short review each week with the community lead.","timeline":["Week 1: audience and positioning","Week 2: content and channel plan","Week 3: launch-ready handoff"],"fit":"Audience research, content strategy, social media planning, and simple campaign measurement.","photo":"assets/people/creator-4.svg","teamSize":"4 people"},"5":{"name":"Elena Park","role":"Founder & service design lead","about":"Goodwell helps people navigate the administrative parts of finding and arranging care.","context":"Our project concerns appointment preparation and service navigation, not clinical advice. Help us understand where the journey becomes unclear and propose service changes grounded in consented research.","responsibilities":["Review existing service touchpoints with the founder.","Prepare a consent-first interview guide and research plan.","Conduct five non-clinical interviews using the supplied recruitment process.","Map the service journey and identify avoidable communication gaps.","Prioritize recommendations by user need, effort, and operational constraints."],"deliverables":["Interview guide and anonymized synthesis","Service journey map with evidence-linked pain points","Prioritized recommendations and a stakeholder presentation"],"collaboration":"Weekly service-design review; no clinical or identifiable patient records are provided.","timeline":["Week 1: research preparation","Week 2: interviews and synthesis","Week 3: service recommendations"],"fit":"Interviewing, qualitative synthesis, service mapping, and handling sensitive topics thoughtfully.","photo":"assets/people/creator-5.svg","teamSize":"6 people"},"6":{"name":"Sam Okafor","role":"Product lead","about":"Relay builds lightweight collaboration tools for small remote teams.","context":"The product works, but its interface copy can sound inconsistent and leave first-time users unsure what to do. Create a practical voice guide and improve the highest-impact screens.","responsibilities":["Audit copy across twelve key product screens.","Define voice principles with examples of helpful and unhelpful language.","Rewrite labels, empty states, validation, and recovery messages.","Explain how the copy supports the user’s next action.","Review the final copy with the designer and prepare an implementation table."],"deliverables":["Concise product voice and tone guide","Before-and-after copy for twelve screens","Implementation sheet with context and rationale"],"collaboration":"Two short working sessions with the product lead and async designer feedback.","timeline":["Days 1–3: audit and voice principles","Days 4–7: rewrites","Days 8–10: review and handoff"],"fit":"UX writing, editing, information hierarchy, and explaining content decisions.","photo":"assets/people/creator-6.svg","teamSize":"3 people"},"7":{"name":"Casey Morgan","role":"Founder & frontend lead","about":"Patchwork gives community spaces a simple way to organize room and event bookings.","context":"Build a booking flow that helps someone choose a space, understand availability, and complete a reservation. You will work from an existing component library and a mocked availability API.","responsibilities":["Map the reservation flow and clarify edge cases with the founder.","Build five responsive screens using React and TypeScript.","Handle unavailable dates, invalid input, and reservation conflicts.","Test keyboard navigation, focus management, and form validation.","Document components and demonstrate the finished flow."],"deliverables":["Five-screen booking flow and reusable form components","Validation tests and an accessibility checklist","Component documentation and handoff recording"],"collaboration":"Weekly frontend review, a shared issue board, and async pull-request feedback.","timeline":["Week 1: flow and components","Weeks 2–3: implementation and edge cases","Week 4: accessibility review and handoff"],"fit":"React, TypeScript, accessible forms, and writing useful component tests.","photo":"assets/people/creator-7.svg","teamSize":"8 people"},"8":{"name":"Jordan Patel","role":"Co-founder & data lead","about":"Tallywell helps subscription businesses understand how customers begin using their products.","context":"We have an anonymized sample of subscription and product-event data. Identify meaningful retention patterns, document what the data cannot tell us, and recommend a focused next experiment.","responsibilities":["Validate identifiers, timestamps, and subscription lifecycle states.","Write reusable cohort queries and define an activation event.","Compare retention across acquisition and activation cohorts.","Use simple statistical checks to describe uncertainty.","Present a prioritized experiment and a measurement plan."],"deliverables":["Reproducible notebook and cohort SQL","Data-quality checklist and metric definitions","Findings deck with one recommended experiment"],"collaboration":"One weekly data review plus async questions with the co-founder.","timeline":["Week 1: audit and cohort definitions","Week 2: analysis","Week 3: findings and experiment brief"],"fit":"SQL, Python, basic statistics, and careful interpretation of behavioral data.","photo":"assets/people/creator-8.svg","teamSize":"4 people"},"9":{"name":"Avery Ellis","role":"Co-founder & product designer","about":"Kindred builds approachable scheduling tools for essential local services.","context":"People need to know what will happen before, during, and after an appointment. Research a focused scheduling journey and prototype a calmer experience with clear preparation information.","responsibilities":["Define the research questions and obtain informed consent.","Interview five participants about appointment planning.","Synthesize needs and map a single end-to-end scheduling journey.","Prototype accessible scheduling and preparation screens in Figma.","Run a small usability round and document changes."],"deliverables":["Research plan, interview synthesis, and journey map","Accessible interactive prototype","Usability findings and developer handoff"],"collaboration":"Weekly design critique with the co-founder and a midpoint research review.","timeline":["Week 1: research","Week 2: prototype","Week 3: usability and handoff"],"fit":"User research, Figma, prototyping, and explaining accessible interaction choices.","photo":"assets/people/creator-9.svg","teamSize":"6 people"},"10":{"name":"Leila Ahmed","role":"Founder & growth lead","about":"Sproutly connects local food growers with customers in their neighborhoods.","context":"Create a launch plan around one neighborhood and a clearly defined audience. The work is planning and asset preparation; no advertising spend or mass outreach is expected.","responsibilities":["Review the product and define the first-launch audience.","Identify audience needs and a concise messaging proposition.","Choose two realistic launch channels and explain why they fit.","Prepare a two-week content calendar and six campaign assets.","Create a KPI tracker with clear event and conversion definitions."],"deliverables":["Audience brief and launch positioning","Two-week calendar and six campaign drafts","Channel rationale and a KPI tracking sheet"],"collaboration":"Two working calls with the founder and async review of campaign drafts.","timeline":["Week 1: audience and channels","Week 2: assets and measurement handoff"],"fit":"Marketing planning, content strategy, and translating goals into measurable actions.","photo":"assets/people/creator-10.svg","teamSize":"3 people"},"11":{"name":"Leo Santos","role":"Founder & backend engineer","about":"Dockside builds integrations that make support teams’ day-to-day tools work together.","context":"Implement a reliable ticket synchronization service between two sandbox APIs. Reliability and maintainable documentation matter more than the number of features.","responsibilities":["Read the sandbox API contracts and map ticket fields.","Implement authenticated request handling and payload validation.","Handle duplicate events, rate limits, and retryable failures.","Add unit and integration tests using provided fixtures.","Document setup, failure recovery, and operational assumptions."],"deliverables":["Node.js integration with validation and retry handling","Automated test suite and example requests","API documentation and a deployment walkthrough"],"collaboration":"Two engineering check-ins per week and pull-request reviews with the founder.","timeline":["Week 1: contracts and architecture","Week 2: core sync","Week 3: reliability and tests","Week 4: documentation and handoff"],"fit":"Node.js, REST APIs, testing, and reasoning about failures and idempotency.","photo":"assets/people/creator-11.svg","teamSize":"8 people"},"12":{"name":"Taylor Nguyen","role":"Operations lead","about":"Clearpath helps growing teams make customer onboarding more consistent.","context":"The team’s onboarding knowledge is spread across documents and people. Map the current process, surface bottlenecks, and recommend a practical workflow without introducing unnecessary tooling.","responsibilities":["Interview five internal stakeholders using a prepared question guide.","Map the current onboarding steps, owners, and handoffs.","Identify unclear responsibilities and recurring delays.","Prioritize improvements by effort, dependency, and expected benefit.","Present a proposed future-state workflow and ownership checklist."],"deliverables":["Current-state workflow and interview synthesis","Prioritized improvement plan","Future-state map and stakeholder presentation"],"collaboration":"Weekly operations review and access to non-sensitive process documentation.","timeline":["Week 1: interviews and current-state map","Week 2: recommendations","Week 3: stakeholder walkthrough"],"fit":"Stakeholder interviews, process mapping, prioritization, and project management.","photo":"assets/people/creator-12.svg","teamSize":"4 people"},"13":{"name":"Sofia Ramirez","role":"Design lead","about":"Looma is building a consistent, accessible interface for a young consumer product.","context":"Audit the product’s most-used screens and create a small component system that engineering can actually adopt. Prioritize clarity and documented states over a large decorative library.","responsibilities":["Audit typography, spacing, color, and repeated interface patterns.","Define a focused token set with accessible color combinations.","Build core Figma components with interaction states and variants.","Test the library against three representative product screens.","Write usage guidance and review the handoff with engineering."],"deliverables":["Core component library and design tokens","Accessible states and three example screens","Usage guidance and engineering handoff"],"collaboration":"Weekly design critique and two engineering working sessions.","timeline":["Week 1: audit and foundations","Week 2: components","Week 3: screen testing","Week 4: guidance and handoff"],"fit":"Figma components, UI design, accessibility, and communicating system rules.","photo":"assets/people/creator-13.svg","teamSize":"6 people"},"14":{"name":"Devon James","role":"Founder & content strategist","about":"Signal Garden helps small product teams communicate clearly with new customers.","context":"Rewrite a five-email onboarding sequence around real user goals. Help the team understand why each message exists and how to evaluate whether it is useful.","responsibilities":["Audit the sequence and map each email to a user need.","Define a primary action and success measure for each message.","Rewrite subjects, preview text, body copy, and calls to action.","Document tone and accessibility considerations.","Propose a simple A/B test without making unsupported growth promises."],"deliverables":["Five revised onboarding emails","Messaging rationale and tone notes","An A/B test plan with measurable outcomes"],"collaboration":"Two content reviews and an async handoff with the founder.","timeline":["Week 1: audit and messaging","Week 2: revisions and test plan"],"fit":"Copywriting, UX writing, lifecycle communication, and basic experiment design.","photo":"assets/people/creator-14.svg","teamSize":"3 people"}};
function enrichDemoListings(listings){for(const j of listings){const p=DemoListingProfiles[j.id];if(!p||j.organizationId)continue;j.demoCreator={...p,id:'sample-creator-'+j.id,email:j.c.toLowerCase().replace(/[^a-z0-9]/g,'')+'.team@example.com'};j.contactEmail=j.c.toLowerCase().replace(/[^a-z0-9]/g,'')+'.team@'+j.c.toLowerCase().replace(/[^a-z0-9]/g,'')+'.example';j.location='Remote · Flexible time zones';}}
function demoPortrait(j,size=''){return `<img class="listing-person-photo ${size}" src="${j.demoCreator.photo}" alt="${esc(j.demoCreator.name)} — illustrated profile" width="48" height="48">`}
function demoCreatorRow(j){return `<button class="listing-creator-row" onclick="showDemoCreator(${j.id})">${demoPortrait(j)}<span><b>${esc(j.demoCreator.name)}</b><small>${esc(j.demoCreator.role)} · ${esc(j.c)}</small></span><span aria-hidden="true">↗</span></button>`}
function demoListingPage(j){const p=j.demoCreator;return `<a class="text-link" href="#explore">← Back to opportunities</a><div class="listing-detail-top">${logo(j)}<div><span class="eyebrow">${esc(j.c)} · ${esc(j.cat)}</span><h1>${esc(j.title)}</h1><p>${esc(j.location)} · ${esc(j.weeks)} · ${esc(p.teamSize)}</p></div></div><div class="listing-detail-grid"><div><section class="panel wide-panel"><span class="eyebrow">THE OPPORTUNITY</span><h2>Work with a clear purpose.</h2><p>${esc(j.desc)}</p><h3>Why this project exists</h3><p>${esc(p.context)}</p><h3>What you’ll work on</h3><ul class="listing-bullet-list">${p.responsibilities.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h3>What you’ll hand over</h3><ul class="listing-bullet-list">${p.deliverables.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h3>Project milestones</h3><ol class="listing-milestones">${p.timeline.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>How you’ll collaborate</h3><p>${esc(p.collaboration)}</p><h3>What makes a strong application</h3><p>${esc(p.fit)} Coursework, volunteering, and personal projects can be useful evidence. Tell us what you personally contributed.</p>${compatibilityHTML(j)}${listingCriteriaHTML(j)}</section><section class="panel wide-panel listing-company-story"><div class="job-top">${logo(j)}<div><span class="eyebrow">ABOUT THE TEAM</span><h2>${esc(j.c)}</h2></div></div><p>${esc(p.about)}</p><div class="tags"><span class="tag">${esc(j.sector)}</span><span class="tag">${esc(p.teamSize)}</span><span class="tag">Remote collaboration</span></div>${demoCreatorRow(j)}</section></div><section class="panel wide-panel listing-apply-card"><span class="eyebrow">PROJECT BUDGET</span><h2>$${j.pay.toLocaleString()}</h2><p>Fixed project budget · ${esc(j.weeks)}</p><div class="listing-budget-note">Agree on milestones, feedback windows, and payment terms before starting. This sample listing does not process project payments.</div><button class="primary" onclick="apply(${j.id})">${applications.includes(j.id)?'View application':'Apply with your profile'} ${icon('arrow',17)}</button><button class="outline" onclick="matchListing(${j.id})">${icon('eye',17)} See my resume fit</button><button class="outline bookmark-detail ${saved.includes(j.id)?'saved':''}" aria-pressed="${saved.includes(j.id)}" onclick="save(${j.id})">${bookmarkIcon(saved.includes(j.id))} ${saved.includes(j.id)?'Saved':'Save opportunity'}</button><button class="outline" onclick="shareListing(${j.id})">${listingShareIcon()} Share listing</button><div class="listing-contact-block"><span class="eyebrow">YOUR PROJECT CONTACT</span>${demoCreatorRow(j)}<a class="listing-contact-email" href="mailto:${esc(j.contactEmail)}">${esc(j.contactEmail)}</a><small>Sample business address · .example email is not deliverable.</small><button class="primary" onclick="messageDemoCreator(${j.id})">${icon('message',17)} Message ${esc(p.name.split(' ')[0])}</button></div></section></div>`}
function showDemoCreator(id){const j=jobs.find(j=>j.id===id);if(!j?.demoCreator)return;const p=j.demoCreator;$('#modal').hidden=false;$('#modal').innerHTML=`<div class="dialog demo-person-dialog" role="dialog" aria-modal="true" aria-labelledby="sample-creator-heading"><button class="close" onclick="closeModal()" aria-label="Close">×</button>${demoPortrait(j,'large')}<span class="eyebrow">PROJECT CREATOR · ${esc(j.c)}</span><h2 id="sample-creator-heading">${esc(p.name)}</h2><p>${esc(p.role)}</p><p>${esc(p.about)}</p><div class="tags">${j.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><h3>Working together</h3><p>${esc(p.collaboration)}</p><p class="resume-hint">Sample contact: ${esc(j.contactEmail)}. This address is not a deliverable inbox.</p><div class="dialog-actions"><button class="primary" onclick="messageDemoCreator(${id})">${icon('message',17)} Message creator</button><a class="outline" href="#project/${id}" onclick="closeModal()">View opportunity</a></div></div>`}
function demoChatState(){try{return JSON.parse(workspaceLocal.getItem('nextwork-demo-chats')||'{}')}catch{return {}}}
function messageDemoCreator(id){if(typeof requireAccount==='function'&&!requireAccount())return;const j=jobs.find(j=>j.id===id);if(!j?.demoCreator)return;const p=j.demoCreator,thread=demoChatState()[id]||[];$('#modal').hidden=false;$('#modal').innerHTML=`<div class="dialog sample-chat-dialog" role="dialog" aria-modal="true" aria-labelledby="sample-chat-heading"><button class="close" onclick="closeModal()" aria-label="Close">×</button><div class="sample-chat-heading">${demoPortrait(j)}<div><h2 id="sample-chat-heading">${esc(p.name)}</h2><p>${esc(p.role)} · ${esc(j.c)}</p></div></div><a class="sample-chat-project" href="#project/${id}" onclick="closeModal()">${icon('briefcase',18)} ${esc(j.title)} →</a><p class="sample-chat-disclosure">Sample conversation · Replies are simulated. Messages stay in your private account and aren’t delivered to an employer.</p><div class="sample-chat-scroll" id="sample-chat-scroll">${thread.length?thread.map(m=>`<div class="sample-chat-bubble ${m.from==='you'?'outgoing':'incoming'}"><small>${m.from==='you'?'You':esc(p.name)+' · Sample reply'}</small><p>${esc(m.text)}</p></div>`).join(''):`<div class="sample-chat-bubble incoming"><small>${esc(p.name)} · Sample greeting</small><p>Hi! Happy to talk about ${esc(j.title.toLowerCase())}. Ask about the scope, timeline, or what to include in your application.</p></div>`}</div><form id="sample-chat-form"><label class="field">Your message<textarea id="sample-chat-text" required maxlength="4000" placeholder="Ask about the project or introduce yourself…"></textarea></label><button class="primary" type="submit">Send message ${icon('send',16)}</button><p id="sample-chat-error" class="review-error" role="alert"></p></form></div>`;const scroll=$('#sample-chat-scroll');scroll.scrollTop=scroll.scrollHeight;$('#sample-chat-form').onsubmit=async e=>{e.preventDefault();const text=$('#sample-chat-text').value.trim();if(!text)return;const button=e.target.querySelector('button');button.disabled=true;const state=demoChatState(),owner=typeof Account==='undefined'?null:Account.user?.id;const messages=state[id]||[];messages.push({from:'you',text,at:new Date().toISOString()},{from:'creator',text:`Thanks for the introduction. ${p.collaboration} A useful next step is to share an example of your work and tell us how you would approach the first milestone: ${p.timeline[0]}.`,at:new Date().toISOString()});state[id]=messages.slice(-60);workspaceLocal.setItem('nextwork-demo-chats',JSON.stringify(state));try{if(typeof saveWorkspace==='function')await saveWorkspace();if(typeof Account!=='undefined'&&Account.user?.id!==owner)return;messageDemoCreator(id)}catch{$('#sample-chat-error').textContent='Could not save your conversation. Reconnect your account and try again.';button.disabled=false}};}
function demoInbox(){const ids=Object.keys(demoChatState()).map(Number).filter(id=>jobs.some(j=>j.id===id&&j.demoCreator));return ids.length?`<section class="sample-inbox"><h2>Project conversation previews</h2><div>${ids.map(id=>{const j=jobs.find(j=>j.id===id);return `<button onclick="messageDemoCreator(${id})">${demoPortrait(j)}<span><b>${esc(j.demoCreator.name)}</b><small>${esc(j.c)} · Sample conversation</small></span></button>`}).join('')}</div></section>`:''}
